INSERT INTO zhishi_notices (id, real, source, publish_date, title, event, audience, deadline, countdown, materials, entry, confidence, priority, points, digest_one, digest_points, raw, url, site, unit, src_generated_at) VALUES ('ahau-024', TRUE, '经济管理学院', '2025-03-26', '经济管理学院纪委召开工作会本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会。院纪委委员、学生党支部', '校内通知', NULL, NULL, NULL, NULL, NULL, 0.5, 'medium', '[{"text": "本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会", "quote": "本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会"}]'::jsonb, '校内通知：经济管理学院纪委召开工作会本网讯 3月26日上午，经济管理学院纪委在经管楼304', '[{"text": "本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会", "quote": "本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会"}]'::jsonb, '本网讯 3月26日上午，经济管理学院纪委在经管楼304会议室召开工作会。院纪委委员、学生党支部书记参加会议，会议由学院党委副书记、纪委书记周涛主持。 会议集中学习了习近平总书记重要文章《健全全面从严治党体系》、习近平总书记在二十届中央纪委四次全会上的重要讲话精神，学习了中央党的建设工作领导小组关于研究部署深入贯彻中央八项规定精神学习教育会议精神及学校2025年全面从严治党工作会议精神。 会议强调，要深化理论武装，加强纪检干部纪法教育和培训，全面提升监督执纪能力和纪法素养；要加强警示教育，抓早抓小、防微杜渐，切实筑牢', 'https://jgxy.ahau.edu.cn/info/1101/19176.htm', '经济管理学院 · 工作动态', 'jgxy', '2026-11-04 13:33:17') ON CONFLICT (id) DO UPDATE SET source=EXCLUDED.source, publish_date=EXCLUDED.publish_date, title=EXCLUDED.title, event=EXCLUDED.event, deadline=EXCLUDED.deadline, points=EXCLUDED.points, digest_one=EXCLUDED.digest_one, digest_points=EXCLUDED.digest_points, raw=EXCLUDED.raw, url=EXCLUDED.url, site=EXCLUDED.site, unit=EXCLUDED.unit, src_generated_at=EXCLUDED.src_generated_at